insert into public.recipes (id, name, meal_type, description, prep_min, kcal, protein, carbs, fat, ingredients, steps, tags, image_url) values
(pg_temp.sid('recipe:Lean carne asada tacos'),'Lean carne asada tacos','dinner','Citrus-marinated flank steak in corn tortillas with fresh toppings.',25,581,51.2,48.3,21.4,array['150 g flank steak, cooked','78 g corn tortilla','40 g onion','60 g tomato','40 g avocado','40 g salsa','30 g Greek yogurt 0% fat','1 tbsp lime juice','1 clove garlic','1/2 tsp ground cumin','1 tbsp fresh coriander']::text[],array['Marinate the steak in lime juice, garlic and cumin for 30 minutes.','Sear in a hot pan for 3 to 4 minutes per side, rest, then slice thinly across the grain.','Warm the tortillas and fill with steak, onion, tomato, avocado, salsa and a spoon of yogurt.']::text[],array['high protein','mexican']::text[],'https://images.pexels.com/photos/7613568/pexels-photo-7613568.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Lighter General Tso''s chicken'),'Lighter General Tso''s chicken','dinner','Sticky ginger-soy chicken with broccoli, baked instead of deep-fried.',25,622,61.4,64.5,12.1,array['170 g chicken breast, cooked','120 g broccoli','150 g white rice, cooked','15 g soy sauce','12 g honey','40 g carrot','5 g olive oil','1 tsp grated fresh ginger','1 clove garlic','1 tbsp rice vinegar','pinch of chilli flakes']::text[],array['Cube the chicken and brown it in a hot pan with the oil.','Stir together soy sauce, honey, vinegar, ginger and garlic, pour over and simmer until glossy.','Steam the broccoli and carrot, then serve everything over rice.']::text[],array['high protein','asian']::text[],'https://images.pexels.com/photos/7111533/pexels-photo-7111533.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Creamy tomato tortellini soup'),'Creamy tomato tortellini soup','dinner','Tomato soup enriched with a little cream cheese, cheese tortellini and spinach.',25,556,51.5,49.8,16.2,array['120 g cheese tortellini, cooked','200 g chopped tomatoes, canned','60 g spinach','30 g light cream cheese','100 g chicken breast, cooked','40 g onion','8 g parmesan','1 clove garlic','300 ml chicken or vegetable stock','1 tsp dried basil']::text[],array['Soften the onion and garlic, add the tomatoes and a cup of stock and simmer for 10 minutes.','Blend until smooth, stir in the cream cheese, then add the tortellini and shredded chicken.','Wilt in the spinach and finish with parmesan.']::text[],array['comfort','one pot']::text[],'https://images.pexels.com/photos/17750146/pexels-photo-17750146.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Ham and egg fried rice'),'Ham and egg fried rice','dinner','Fast fried rice built on lean ham, eggs and plenty of veg.',15,659,40.6,72.6,21.7,array['100 g ham, sliced','200 g white rice, cooked','100 g eggs, whole','60 g peas, frozen','50 g carrot','15 g soy sauce','8 g olive oil','2 spring onions','1 clove garlic']::text[],array['Heat the oil in a wok and scramble the eggs, then set aside.','Stir-fry the carrot, peas and chopped ham for 2 minutes.','Add the cold rice, soy sauce and eggs and toss until piping hot.']::text[],array['quick','meal prep']::text[],'https://images.pexels.com/photos/28503587/pexels-photo-28503587.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Honey mustard chicken with potatoes'),'Honey mustard chicken with potatoes','dinner','Sheet-pan chicken with a light honey and mustard glaze.',35,608,62.4,59.1,13.5,array['180 g chicken breast, cooked','12 g honey','15 g Dijon mustard','200 g potato, boiled','120 g green beans','6 g olive oil','1 clove garlic','1/2 tsp paprika']::text[],array['Whisk the honey, mustard, garlic and paprika and coat the chicken.','Roast the chicken and halved potatoes at 200C for 25 to 30 minutes.','Steam the green beans and serve alongside.']::text[],array['high protein','one pan']::text[],'https://images.pexels.com/photos/21517324/pexels-photo-21517324.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Black bean and beef tostadas'),'Black bean and beef tostadas','dinner','Crisp corn tostadas piled with beans, lean beef and avocado.',20,658,46.9,71.5,22.3,array['78 g corn tortilla','120 g black beans, cooked','100 g beef mince 5% fat, cooked','50 g avocado','30 g mixed salad leaves','40 g salsa','15 g cheddar cheese','1/2 lime','1/2 tsp chilli powder']::text[],array['Bake the tortillas at 200C for 6 to 8 minutes until crisp.','Warm the beans and the beef mince with chilli powder.','Layer beans, beef, leaves, salsa, cheese and sliced avocado on each tostada.']::text[],array['mexican','high protein']::text[],'https://images.pexels.com/photos/19725462/pexels-photo-19725462.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Southwest tortellini pasta salad'),'Southwest tortellini pasta salad','dinner','Cold tortellini tossed with beans, corn and a yogurt-salsa dressing.',20,705,61.0,85.7,13.8,array['150 g cheese tortellini, cooked','80 g black beans, cooked','60 g sweetcorn','80 g tomato','60 g bell pepper','60 g Greek yogurt 0% fat','40 g salsa','100 g chicken breast, cooked','1 tbsp lime juice','1 tbsp chopped coriander']::text[],array['Cook the tortellini, drain and cool under cold water.','Mix the yogurt, salsa and lime juice into a dressing.','Toss everything together with the chopped veg, beans and chicken.']::text[],array['meal prep','no cook']::text[],'https://images.pexels.com/photos/9399946/pexels-photo-9399946.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Cajun chicken and sausage kebabs'),'Cajun chicken and sausage kebabs','dinner','Spiced chicken and chicken sausage skewers with peppers, served on rice.',30,663,61.2,57.2,19.1,array['140 g chicken breast, cooked','70 g chicken sausage, cooked','100 g bell pepper','80 g courgette','50 g onion','150 g white rice, cooked','6 g olive oil','2 tsp cajun seasoning','1/2 tsp garlic powder']::text[],array['Toss the chicken, sausage slices and chunks of veg with oil and cajun seasoning.','Thread onto skewers and grill or griddle for 12 to 15 minutes, turning often.','Serve on rice.']::text[],array['high protein','bbq']::text[],'https://images.pexels.com/photos/5643427/pexels-photo-5643427.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Turkey meatballs arrabbiata'),'Turkey meatballs arrabbiata','dinner','Spicy tomato sauce with baked turkey meatballs over pasta.',35,741,61.3,74.7,20.9,array['150 g turkey mince, cooked','15 g breadcrumbs','25 g eggs, whole','200 g chopped tomatoes, canned','170 g pasta, cooked','40 g onion','8 g parmesan','2 cloves garlic','1/2 tsp chilli flakes','1 tsp dried oregano']::text[],array['Mix the turkey, breadcrumbs, egg and oregano, shape into balls and bake at 200C for 15 minutes.','Simmer the tomatoes with garlic, onion and chilli for 15 minutes.','Add the meatballs to the sauce and serve over pasta with parmesan.']::text[],array['high protein','meal prep']::text[],'https://images.pexels.com/photos/31284951/pexels-photo-31284951.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Smash burger with tomato and lettuce'),'Smash burger with tomato and lettuce','dinner','Thin, crisp-edged beef patties on a wholemeal bun.',20,659,53.0,68.0,19.9,array['140 g beef mince 5% fat, cooked','70 g wholemeal burger bun','20 g cheddar cheese','60 g tomato','25 g mixed salad leaves','150 g potato, boiled','10 g tomato ketchup','1 tsp mustard','4 pickle slices']::text[],array['Roll the beef into two balls and smash flat in a very hot dry pan; season and cook 2 minutes per side.','Melt the cheese on top and toast the bun.','Build the burger and serve with roasted potato wedges.']::text[],array['high protein','quick']::text[],'https://images.pexels.com/photos/36741809/pexels-photo-36741809.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Walking taco bowl'),'Walking taco bowl','dinner','All the walking taco flavour with a handful of chips and lots of toppings in a bowl.',20,690,59.1,54.0,27.8,array['140 g turkey mince, cooked','30 g tortilla chips','80 g black beans, cooked','50 g salsa','40 g mixed salad leaves','20 g cheddar cheese','40 g Greek yogurt 0% fat','50 g sweetcorn','2 tsp taco seasoning']::text[],array['Brown the turkey with taco seasoning and a splash of water.','Crush the chips into the bowl, then spoon over the turkey and beans.','Top with leaves, corn, salsa, cheese and yogurt.']::text[],array['fun','high protein']::text[],'https://images.pexels.com/photos/7613568/pexels-photo-7613568.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Creamy chicken and gnocchi'),'Creamy chicken and gnocchi','dinner','Pan-fried gnocchi and chicken in a light creamy sauce with spinach.',25,666,63.9,58.4,19.1,array['150 g chicken breast, cooked','170 g gnocchi, cooked','60 g spinach','30 g light cream cheese','100 ml milk, semi-skimmed','10 g parmesan','5 g olive oil','1 clove garlic','black pepper to taste']::text[],array['Pan-fry the gnocchi in the oil until golden and set aside.','Warm the milk with the cream cheese and garlic until smooth, add the chicken and spinach.','Stir the gnocchi back in and top with parmesan.']::text[],array['comfort','high protein']::text[],'https://images.pexels.com/photos/31329415/pexels-photo-31329415.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Hummus and edamame veggie wrap'),'Hummus and edamame veggie wrap','dinner','A crunchy plant-based wrap with edamame, hummus and raw veg.',10,723,32.9,90.7,27.5,array['124 g tortilla wrap','60 g hummus','100 g edamame','50 g carrot','60 g cucumber','30 g spinach','30 g feta','1 tsp lemon juice']::text[],array['Spread the hummus over the wraps.','Layer the edamame, grated carrot, cucumber, spinach and crumbled feta.','Squeeze over lemon, roll tightly and slice in half.']::text[],array['vegetarian','no cook']::text[],'https://images.pexels.com/photos/30392949/pexels-photo-30392949.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Chicken red curry'),'Chicken red curry','dinner','Fragrant red curry with light coconut milk and vegetables.',30,654,58.3,63.3,17.7,array['160 g chicken breast, cooked','150 g light coconut milk','20 g curry paste','80 g bell pepper','80 g courgette','160 g white rice, cooked','60 g green beans','1 tsp fish sauce','1/2 lime','1 tbsp fresh basil']::text[],array['Fry the curry paste for a minute, pour in the coconut milk and a splash of water.','Add the chicken and vegetables and simmer for 12 minutes.','Finish with lime and basil and serve over rice.']::text[],array['high protein','asian']::text[],'https://images.pexels.com/photos/31653135/pexels-photo-31653135.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Kung pao chicken'),'Kung pao chicken','dinner','Spicy-sweet stir-fry with peanuts, peppers and courgette.',25,739,66.1,61.9,24.4,array['170 g chicken breast, cooked','25 g peanuts','100 g bell pepper','80 g courgette','150 g white rice, cooked','15 g soy sauce','8 g honey','5 g olive oil','1 clove garlic','1 tsp grated fresh ginger','3 dried chillies','1 tbsp rice vinegar']::text[],array['Stir-fry the chicken in oil until browned, then add the vegetables and chillies.','Add soy sauce, honey, vinegar, garlic and ginger and toss for 2 minutes.','Stir through the peanuts and serve on rice.']::text[],array['high protein','asian']::text[],'https://images.pexels.com/photos/2928380/pexels-photo-2928380.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Quinoa nourish bowl'),'Quinoa nourish bowl','dinner','A big plant-forward bowl: quinoa, roasted sweet potato, chickpeas and greens.',25,694,31.4,104.8,18.7,array['150 g quinoa, cooked','150 g sweet potato, baked','120 g chickpeas, cooked','40 g kale','50 g avocado','60 g Greek yogurt 0% fat','20 g feta','1 tbsp lemon juice','1/2 tsp paprika','1 tsp tahini (optional)']::text[],array['Roast the sweet potato cubes and chickpeas with paprika at 200C for 25 minutes.','Massage the kale with lemon juice.','Build the bowl on the quinoa and finish with sliced avocado, feta and a yogurt drizzle.']::text[],array['vegetarian','high fibre']::text[],'https://images.pexels.com/photos/19150338/pexels-photo-19150338.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Mushroom and black bean tacos'),'Mushroom and black bean tacos','dinner','Savoury seared mushrooms and beans in warm corn tortillas.',20,621,33.1,79.1,22.7,array['78 g corn tortilla','200 g mushrooms','120 g black beans, cooked','50 g avocado','40 g salsa','50 g Greek yogurt 0% fat','20 g cheddar cheese','5 g olive oil','1/2 tsp smoked paprika','1/2 lime','1 tbsp chopped coriander']::text[],array['Sear the sliced mushrooms in the oil with smoked paprika until deeply browned.','Warm the beans and tortillas.','Fill with mushrooms and beans and top with avocado, salsa, yogurt and cheese.']::text[],array['vegetarian','mexican']::text[],'https://images.pexels.com/photos/17429146/pexels-photo-17429146.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Turkey sloppy joes'),'Turkey sloppy joes','dinner','Saucy tomato-pepper turkey on a toasted wholemeal bun.',25,610,53.3,62.0,18.2,array['150 g turkey mince, cooked','70 g wholemeal burger bun','100 g chopped tomatoes, canned','40 g onion','60 g bell pepper','15 g tomato ketchup','80 g sweetcorn','1 tsp worcestershire sauce','1 clove garlic','1/2 tsp smoked paprika']::text[],array['Soften the onion and pepper, add the turkey and cook until browned.','Stir in the tomatoes, ketchup, worcestershire and spices and simmer for 10 minutes.','Pile onto the toasted bun and serve with corn.']::text[],array['high protein','family']::text[],'https://images.pexels.com/photos/6358875/pexels-photo-6358875.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Chicken dumpling soup'),'Chicken dumpling soup','dinner','A light ginger broth with dumplings, greens and carrots.',20,667,48.0,77.6,17.5,array['180 g chicken dumplings, cooked','80 g chicken breast, cooked','50 g spinach','50 g carrot','10 g soy sauce','80 g egg noodles, cooked','300 ml chicken stock','1 tsp grated fresh ginger','2 spring onions']::text[],array['Simmer the stock with ginger, soy sauce and carrot for 8 minutes.','Add the dumplings and noodles and cook according to the pack.','Stir in the shredded chicken and spinach and top with spring onions.']::text[],array['comfort','quick']::text[],'https://images.pexels.com/photos/3533865/pexels-photo-3533865.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Thai green curry chicken meatballs'),'Thai green curry chicken meatballs','dinner','Baked chicken meatballs in a green curry coconut sauce.',35,644,58.5,60.1,17.7,array['150 g chicken breast, cooked','10 g breadcrumbs','25 g eggs, whole','120 g light coconut milk','15 g curry paste','80 g broccoli','150 g white rice, cooked','1 tbsp chopped coriander','1/2 lime','1 tsp fish sauce']::text[],array['Mince or finely chop the chicken, mix with breadcrumbs, egg and coriander, shape into balls and bake for 15 minutes.','Simmer the curry paste with the coconut milk, add the broccoli and meatballs.','Serve with rice and a squeeze of lime.']::text[],array['high protein','asian']::text[],'https://images.pexels.com/photos/31029754/pexels-photo-31029754.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Green chile chicken burritos'),'Green chile chicken burritos','dinner','Chicken, beans and rice rolled up and finished with salsa and a little cheese.',30,813,69.9,86.7,19.3,array['62 g tortilla wrap','140 g chicken breast, cooked','80 g black beans, cooked','100 g white rice, cooked','80 g salsa','25 g cheddar cheese','40 g Greek yogurt 0% fat','1 tbsp chopped green chiles','1/2 tsp ground cumin']::text[],array['Mix the chicken, beans and rice with cumin and a spoon of salsa.','Roll in the tortilla, top with the rest of the salsa and cheese and bake at 200C for 12 minutes.','Serve with a dollop of yogurt.']::text[],array['mexican','meal prep']::text[],'https://images.pexels.com/photos/27365284/pexels-photo-27365284.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Chicken, bacon and avocado wrap'),'Chicken, bacon and avocado wrap','dinner','A satisfying wrap with just enough bacon for flavour.',10,692,57.1,66.0,22.7,array['62 g tortilla wrap','120 g chicken breast, cooked','50 g avocado','25 g bacon rashers, grilled','30 g spinach','60 g tomato','40 g Greek yogurt 0% fat','120 g sweet potato, baked','1 tsp lime juice','black pepper to taste']::text[],array['Mash the avocado with the yogurt and lime juice.','Spread over the wrap and add the chicken, crisp bacon, spinach and tomato.','Roll up and serve with baked sweet potato.']::text[],array['quick','high protein']::text[],'https://images.pexels.com/photos/10027451/pexels-photo-10027451.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Loaded taco salad'),'Loaded taco salad','dinner','Crunchy leaves topped with seasoned beef, beans, corn and cheese.',20,605,54.1,52.3,21.5,array['120 g beef mince 5% fat, cooked','80 g mixed salad leaves','80 g black beans, cooked','50 g sweetcorn','80 g tomato','20 g cheddar cheese','50 g salsa','50 g Greek yogurt 0% fat','20 g tortilla chips','2 tsp taco seasoning','1/2 lime']::text[],array['Brown the beef with taco seasoning.','Pile the leaves into a bowl and add the beef, beans, corn and tomato.','Top with cheese, salsa, yogurt and crushed chips.']::text[],array['high protein','salad']::text[],'https://images.pexels.com/photos/32536642/pexels-photo-32536642.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Chicken and matzo ball soup'),'Chicken and matzo ball soup','dinner','Classic comforting chicken soup with light matzo dumplings.',40,645,61.0,58.9,17.2,array['150 g chicken breast, cooked','40 g matzo meal','50 g eggs, whole','80 g carrot','50 g onion','60 g egg noodles, cooked','5 g olive oil','400 ml chicken stock','1 celery stick','1 tbsp fresh dill']::text[],array['Mix the matzo meal with the egg and oil, chill for 20 minutes, then roll into small balls.','Simmer the stock with the carrot, onion and celery for 15 minutes.','Poach the matzo balls for 20 minutes, add the shredded chicken and noodles and finish with dill.']::text[],array['comfort','high protein']::text[],'https://images.pexels.com/photos/3533865/pexels-photo-3533865.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Beef gyros with tzatziki'),'Beef gyros with tzatziki','dinner','Spiced sliced beef in a warm pita with a yogurt-cucumber sauce.',30,508,55.0,42.5,13.9,array['130 g sirloin steak, cooked','60 g wholemeal pita','80 g Greek yogurt 0% fat','80 g cucumber','70 g tomato','30 g onion','20 g mixed salad leaves','1/2 tsp dried oregano','1 clove garlic','1 tsp lemon juice']::text[],array['Season the beef with oregano, garlic and lemon and sear, then slice thinly.','Stir grated cucumber and garlic into the yogurt.','Fill the pita with beef, tomato, onion, leaves and a generous spoon of tzatziki.']::text[],array['high protein','mediterranean']::text[],'https://images.pexels.com/photos/6941000/pexels-photo-6941000.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Chicken pot pie with a light topping'),'Chicken pot pie with a light topping','dinner','A creamy chicken and veg filling under a thin flaky-style crust.',45,677,61.3,71.8,15.3,array['150 g chicken breast, cooked','60 g peas, frozen','60 g carrot','100 g potato, boiled','150 ml milk, semi-skimmed','35 g plain flour','8 g butter','40 g onion','1/2 tsp dried thyme','100 ml chicken stock']::text[],array['Make a quick sauce: melt the butter, stir in 20 g flour, then whisk in the milk and a splash of stock until thick.','Fold in the chicken, peas, carrot, potato and thyme and spoon into a dish.','Mix the remaining flour with a little water into a paste, pat out a thin lid, cover and bake at 200C for 25 minutes.']::text[],array['comfort','family']::text[],'https://images.pexels.com/photos/13105572/pexels-photo-13105572.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Spinach, chicken and mozzarella calzone'),'Spinach, chicken and mozzarella calzone','dinner','A folded pizza pocket with a lean chicken and spinach filling.',35,744,61.5,82.3,17.0,array['150 g pizza dough, baked','50 g mozzarella','100 g chicken breast, cooked','50 g spinach','80 g chopped tomatoes, canned','40 g mixed salad leaves','1 clove garlic','1/2 tsp dried oregano']::text[],array['Roll the dough into a circle and spread half with tomato.','Top that half with chicken, spinach and mozzarella, fold over and seal the edge.','Bake at 220C for 18 to 20 minutes and serve with a side salad.']::text[],array['comfort','high protein']::text[],'https://images.pexels.com/photos/6068717/pexels-photo-6068717.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Quinoa and chickpea burger'),'Quinoa and chickpea burger','dinner','Hearty vegetarian patties baked until crisp outside.',35,763,35.0,110.1,22.1,array['100 g quinoa, cooked','120 g chickpeas, cooked','50 g eggs, whole','25 g oats, dry','70 g wholemeal burger bun','50 g avocado','50 g tomato','20 g mixed salad leaves','1/2 tsp ground cumin','1 clove garlic','1 tbsp chopped parsley']::text[],array['Mash the chickpeas and mix with the quinoa, egg, oats and spices.','Shape into patties and bake at 200C for 20 minutes, turning once.','Serve in the bun with avocado, tomato and leaves.']::text[],array['vegetarian','high fibre']::text[],'https://images.pexels.com/photos/20741663/pexels-photo-20741663.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Slow-braised beef ragu with pappardelle'),'Slow-braised beef ragu with pappardelle','dinner','Rich, slow-cooked lean beef sauce over wide pasta ribbons.',60,730,57.8,63.7,26.6,array['140 g braising beef, cooked lean','160 g pasta, cooked','150 g chopped tomatoes, canned','40 g carrot','50 g onion','10 g parmesan','5 g olive oil','50 ml red wine (optional)','2 cloves garlic','1 sprig rosemary','200 ml beef stock']::text[],array['Brown the beef, then soften the onion, carrot and garlic in the same pan.','Add the tomatoes, stock and rosemary, cover and simmer for 1.5 hours until it falls apart.','Shred the beef into the sauce and serve over pasta with parmesan.']::text[],array['comfort','meal prep']::text[],'https://images.pexels.com/photos/19842781/pexels-photo-19842781.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Beef and cabbage roll soup'),'Beef and cabbage roll soup','dinner','All the cabbage roll flavour in one pot with rice and tomato.',40,495,42.3,58.9,10.1,array['130 g beef mince 5% fat, cooked','200 g cabbage','120 g white rice, cooked','150 g chopped tomatoes, canned','50 g onion','40 g carrot','300 ml beef stock','1 tsp paprika','1 bay leaf']::text[],array['Brown the beef with the onion and carrot.','Add the cabbage, tomatoes, stock and paprika and simmer for 20 minutes.','Stir in the cooked rice and heat through.']::text[],array['comfort','one pot']::text[],'https://images.pexels.com/photos/31372406/pexels-photo-31372406.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Peanut noodles with chicken'),'Peanut noodles with chicken','dinner','Silky peanut-soy noodles with crunchy veg and shredded chicken.',20,650,55.6,61.4,20.5,array['180 g rice noodles, cooked','25 g peanut butter','15 g soy sauce','120 g chicken breast, cooked','50 g carrot','60 g cucumber','60 g edamame','1 tbsp lime juice','pinch of chilli flakes','1 clove garlic']::text[],array['Whisk the peanut butter, soy sauce, lime and garlic with a splash of warm water.','Toss with the noodles, chicken and edamame.','Top with carrot and cucumber ribbons and chilli.']::text[],array['quick','asian']::text[],'https://images.pexels.com/photos/6488937/pexels-photo-6488937.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Street corn chicken rice bowl'),'Street corn chicken rice bowl','dinner','Charred corn, spiced chicken and a tangy yogurt-lime sauce over rice.',25,722,70.7,80.8,12.5,array['160 g chicken breast, cooked','150 g white rice, cooked','100 g sweetcorn','60 g black beans, cooked','20 g feta','50 g Greek yogurt 0% fat','50 g bell pepper','1/2 lime','1/2 tsp chilli powder','1 tbsp chopped coriander']::text[],array['Char the corn in a dry hot pan until blackened in spots.','Season and sear the chicken, then slice.','Build the bowl on rice with beans, pepper, chicken and corn and finish with crumbled feta and lime yogurt.']::text[],array['high protein','mexican']::text[],'https://images.pexels.com/photos/24738520/pexels-photo-24738520.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:BBQ pulled pork sandwich with pineapple slaw'),'BBQ pulled pork sandwich with pineapple slaw','dinner','Lean shredded pork in smoky BBQ sauce with a fruity crunchy slaw.',40,549,52.8,64.4,9.1,array['150 g pork tenderloin, cooked','34 g BBQ sauce','70 g wholemeal burger bun','80 g cabbage','60 g pineapple','40 g mango','40 g Greek yogurt 0% fat','1/2 tsp smoked paprika','1 tsp lime juice']::text[],array['Simmer or slow-cook the pork with BBQ sauce and paprika until it shreds easily.','Toss the cabbage, pineapple and mango with the yogurt and lime juice.','Pile the pork into the bun and top with the slaw.']::text[],array['high protein','bbq']::text[],'https://images.pexels.com/photos/34495401/pexels-photo-34495401.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Light shrimp alfredo'),'Light shrimp alfredo','dinner','A creamy garlic sauce made with cream cheese and parmesan instead of heavy cream.',20,657,60.3,65.3,17.3,array['150 g prawns, cooked','180 g pasta, cooked','40 g light cream cheese','100 ml milk, semi-skimmed','15 g parmesan','40 g spinach','5 g olive oil','1 clove garlic','black pepper to taste','1/2 tsp lemon zest']::text[],array['Warm the milk with the cream cheese, garlic and parmesan until smooth.','Sear the prawns in the oil for 2 minutes.','Toss the pasta, prawns, spinach and sauce together.']::text[],array['quick','high protein']::text[],'https://images.pexels.com/photos/31235407/pexels-photo-31235407.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Chicken caesar wrap'),'Chicken caesar wrap','dinner','A caesar wrap with a yogurt-based dressing.',10,654,62.3,68.1,14.0,array['62 g tortilla wrap','140 g chicken breast, cooked','50 g mixed salad leaves','12 g parmesan','50 g Greek yogurt 0% fat','60 g tomato','150 g potato, boiled','1 tsp lemon juice','1/2 clove garlic','1/2 tsp Dijon mustard']::text[],array['Stir the yogurt with lemon juice, garlic, mustard and half the parmesan.','Toss the leaves and chicken in the dressing.','Pile onto the wrap with tomato, roll up and serve with boiled potatoes.']::text[],array['quick','high protein']::text[],'https://images.pexels.com/photos/10027451/pexels-photo-10027451.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Lemon parmesan chicken pasta'),'Lemon parmesan chicken pasta','dinner','Bright lemony pasta with seared chicken and a little parmesan.',25,719,66.8,65.5,19.8,array['150 g chicken breast, cooked','180 g pasta, cooked','15 g parmesan','50 g spinach','8 g olive oil','50 g peas, frozen','zest and juice of 1/2 lemon','1 clove garlic','black pepper to taste']::text[],array['Sear the chicken, rest, then slice.','Toss the hot pasta with oil, garlic, lemon zest, juice, peas and spinach until wilted.','Fold in the chicken and parmesan.']::text[],array['high protein','quick']::text[],'https://images.pexels.com/photos/1438672/pexels-photo-1438672.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Beef lomo saltado'),'Beef lomo saltado','dinner','Peruvian-style beef and onion stir-fry with tomatoes, served over rice with a few fries.',25,703,53.6,74.2,20.3,array['150 g sirloin steak, cooked','80 g onion','100 g tomato','150 g white rice, cooked','100 g potato, boiled','15 g soy sauce','6 g olive oil','1 clove garlic','1 tbsp red wine vinegar','1 tbsp chopped coriander']::text[],array['Roast the potato wedges at 220C for 25 minutes.','Stir-fry the sliced beef in a very hot pan for 2 minutes, add the onion and tomato.','Splash in the soy sauce and vinegar, toss in the potatoes and serve on rice.']::text[],array['high protein','latin']::text[],'https://images.pexels.com/photos/34429558/pexels-photo-34429558.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Tomato mozzarella pizza'),'Tomato mozzarella pizza','dinner','A thin homemade pizza with fresh mozzarella and rocket.',30,765,59.8,83.2,19.6,array['150 g pizza dough, baked','70 g mozzarella','80 g chopped tomatoes, canned','60 g tomato','30 g mixed salad leaves','80 g chicken breast, cooked','6 fresh basil leaves','1 clove garlic','1 tsp olive oil to drizzle']::text[],array['Stretch the dough thin and spread with the tomato, garlic and a pinch of salt.','Top with torn mozzarella and sliced tomato and bake at 240C for 10 to 12 minutes.','Scatter over the leaves, chicken and basil.']::text[],array['vegetarian','weekend']::text[],'https://images.pexels.com/photos/6068717/pexels-photo-6068717.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Salmon rice bowl'),'Salmon rice bowl','dinner','Teriyaki-style salmon over rice with edamame, cucumber and avocado.',25,673,45.1,61.1,26.8,array['140 g salmon fillet, cooked','150 g white rice, cooked','70 g edamame','60 g cucumber','40 g avocado','12 g soy sauce','8 g honey','1 tsp rice vinegar','1 tsp sesame seeds','1 spring onion']::text[],array['Brush the salmon with soy sauce and honey and bake at 200C for 10 to 12 minutes.','Dress the cucumber with a splash of rice vinegar.','Flake the salmon over rice and top with edamame, cucumber, avocado and sesame.']::text[],array['omega-3','high protein']::text[],'https://images.pexels.com/photos/28992231/pexels-photo-28992231.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Salmon tacos with crunchy slaw'),'Salmon tacos with crunchy slaw','dinner','Seared salmon in corn tortillas with a lime-yogurt cabbage slaw.',25,583,42.7,46.9,25.3,array['140 g salmon fillet, cooked','78 g corn tortilla','80 g cabbage','50 g Greek yogurt 0% fat','40 g avocado','30 g salsa','1/2 lime','1/2 tsp chilli powder','1 tbsp chopped coriander']::text[],array['Rub the salmon with chilli powder and sear or bake until just cooked, then flake.','Mix the cabbage with the yogurt and lime juice for the slaw.','Fill warm tortillas with salmon, slaw, avocado and salsa.']::text[],array['omega-3','mexican']::text[],'https://images.pexels.com/photos/39433053/pexels-photo-39433053.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Mediterranean turkey meatball bowl'),'Mediterranean turkey meatball bowl','dinner','Herby turkey meatballs on couscous with cucumber, tomato and feta.',35,697,58.9,56.9,26.0,array['150 g turkey mince, cooked','160 g couscous, cooked','70 g cucumber','80 g tomato','25 g feta','40 g hummus','10 g breadcrumbs','25 g eggs, whole','1 tsp dried oregano','1 tbsp lemon juice','1 tbsp chopped parsley']::text[],array['Mix the turkey, breadcrumbs, egg and oregano, shape into balls and bake at 200C for 15 minutes.','Fluff the couscous with lemon juice and parsley.','Serve the meatballs on the couscous with cucumber, tomato, feta and a spoon of hummus.']::text[],array['high protein','mediterranean']::text[],'https://images.pexels.com/photos/13788174/pexels-photo-13788174.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Creamy garlic and herb pasta'),'Creamy garlic and herb pasta','dinner','Light herb cream cheese sauce with cherry tomatoes and chicken.',20,657,62.2,66.8,14.6,array['180 g pasta, cooked','40 g light cream cheese','130 g chicken breast, cooked','100 g tomato','40 g spinach','10 g parmesan','60 ml milk, semi-skimmed','1 clove garlic','1 tsp mixed herbs','black pepper to taste']::text[],array['Warm the cream cheese with the milk, garlic and herbs until smooth.','Toss through the pasta, chicken and halved tomatoes.','Wilt in the spinach and finish with parmesan.']::text[],array['quick','comfort']::text[],'https://images.pexels.com/photos/1438672/pexels-photo-1438672.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Beef cevapi with pita and yogurt'),'Beef cevapi with pita and yogurt','dinner','Grilled spiced minced-beef rolls served in pita with onion and yogurt.',30,508,54.3,45.9,12.8,array['150 g beef mince 5% fat, cooked','60 g wholemeal pita','50 g onion','70 g Greek yogurt 0% fat','70 g tomato','60 g bell pepper','50 g cucumber','1 clove garlic','1 tsp paprika','pinch of bicarbonate of soda']::text[],array['Mix the mince with garlic, paprika and a splash of water, shape into short finger-sized rolls.','Grill or pan-fry for 8 to 10 minutes, turning until browned.','Serve in the pita with onion, tomato, pepper, cucumber and yogurt.']::text[],array['high protein','balkan']::text[],'https://images.pexels.com/photos/25856530/pexels-photo-25856530.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Chicken panang curry'),'Chicken panang curry','dinner','A rich peanutty panang-style curry that stays light on calories.',30,698,60.1,60.4,23.5,array['160 g chicken breast, cooked','150 g light coconut milk','20 g curry paste','12 g peanut butter','80 g bell pepper','60 g green beans','150 g white rice, cooked','1 tbsp lime juice','1 tsp fish sauce','6 basil leaves']::text[],array['Fry the curry paste with the peanut butter for a minute.','Add the coconut milk, chicken, pepper and beans and simmer for 12 minutes.','Finish with basil and lime and serve over rice.']::text[],array['high protein','asian']::text[],'https://images.pexels.com/photos/31653135/pexels-photo-31653135.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Baked sweet and sour chicken'),'Baked sweet and sour chicken','dinner','Crisp-baked chicken in a pineapple and pepper sweet-sour sauce.',30,617,59.0,76.4,7.0,array['170 g chicken breast, cooked','100 g pineapple','100 g bell pepper','40 g onion','150 g white rice, cooked','20 g tomato ketchup','8 g honey','1 tbsp rice vinegar','1 tbsp soy sauce','1 clove garlic']::text[],array['Bake the cubed chicken at 220C for 15 minutes until golden.','Simmer the ketchup, honey, vinegar, soy sauce and garlic with the peppers, onion and pineapple.','Toss the chicken through the sauce and serve on rice.']::text[],array['high protein','asian']::text[],'https://images.pexels.com/photos/5848495/pexels-photo-5848495.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Lean ground beef tacos'),'Lean ground beef tacos','dinner','Weeknight tacos with lean beef, crisp lettuce and tomato.',20,623,57.0,57.3,19.4,array['140 g beef mince 5% fat, cooked','78 g corn tortilla','70 g tomato','30 g mixed salad leaves','20 g cheddar cheese','40 g salsa','40 g Greek yogurt 0% fat','60 g black beans, cooked','2 tsp taco seasoning','1/2 lime']::text[],array['Brown the beef with taco seasoning and a splash of water.','Warm the tortillas and the beans.','Fill with beef, beans, leaves, tomato, cheese, salsa and yogurt.']::text[],array['high protein','mexican']::text[],'https://images.pexels.com/photos/7613568/pexels-photo-7613568.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Smoky black bean burger'),'Smoky black bean burger','dinner','A firm homemade black bean patty on a wholemeal bun.',30,799,37.2,125.8,18.5,array['150 g black beans, cooked','30 g oats, dry','50 g eggs, whole','70 g wholemeal burger bun','50 g avocado','50 g tomato','150 g sweet potato, baked','20 g mixed salad leaves','1/2 tsp smoked paprika','1/2 tsp ground cumin','1 clove garlic']::text[],array['Mash the beans with the oats, egg and spices and shape into a patty.','Pan-fry or bake for 6 minutes per side.','Serve in the bun with avocado, tomato, leaves and baked sweet potato.']::text[],array['vegetarian','high fibre']::text[],'https://images.pexels.com/photos/20741663/pexels-photo-20741663.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Thai basil chicken with rice'),'Thai basil chicken with rice','dinner','Punchy minced chicken stir-fry with green beans, chilli and basil.',20,653,63.3,56.5,17.4,array['160 g chicken breast, cooked','100 g green beans','60 g bell pepper','160 g white rice, cooked','50 g eggs, whole','12 g soy sauce','6 g olive oil','1 tbsp fresh basil','1 clove garlic','1 red chilli','1 tsp fish sauce']::text[],array['Stir-fry the minced chicken in the oil until browned, then add garlic, chilli, beans and pepper.','Add the soy and fish sauce and toss until glossy, then stir in the basil.','Serve over rice topped with a fried egg.']::text[],array['quick','high protein']::text[],'https://images.pexels.com/photos/12153472/pexels-photo-12153472.jpeg?auto=compress&cs=tinysrgb&w=800'),
(pg_temp.sid('recipe:Lighter Swedish meatballs'),'Lighter Swedish meatballs','dinner','Tender beef meatballs in a creamy mushroom gravy with potatoes.',35,623,56.1,65.8,15.3,array['140 g beef mince 5% fat, cooked','15 g breadcrumbs','25 g eggs, whole','80 g mushrooms','100 ml milk, semi-skimmed','40 g Greek yogurt 0% fat','200 g potato, boiled','8 g plain flour','100 ml beef stock','1/4 tsp ground allspice','1 tbsp fresh dill']::text[],array['Mix the beef, breadcrumbs, egg and allspice, shape into balls and bake at 200C for 15 minutes.','Fry the mushrooms, stir in the flour, then whisk in the milk and stock until thick; finish with yogurt.','Add the meatballs to the gravy and serve with boiled potatoes and dill.']::text[],array['comfort','high protein']::text[],'https://images.pexels.com/photos/36958915/pexels-photo-36958915.jpeg?auto=compress&cs=tinysrgb&w=800')
